{"code":"def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    if not pts: return out
    color=pts[0][2]
    if len(pts)>=2:
        r1,c1,_=pts[0]; r2,c2,_=pts[-1]
        # diagonal slope +1 or -1
        if (c2-c1)*(r2-r1)>0:
            # c-r constant; fill lower-left side
            k=c1-r1
            for r in range(len(grid)):
                for c in range(len(grid[0])):
                    if c-r<=k: out[r][c]=color
        else:
            # c+r constant; fill lower-right side
            k=c1+r1
            for r in range(len(grid)):
                for c in range(len(grid[0])):
                    if c+r>=k: out[r][c]=color
    return out"}

